rows=[json.loads(x) for x in PATH.read_text(encoding='utf-8').splitlines() if x.strip()];by={r['id']:r for r in rows};ids=[f'ar-c2-u01-p{i:02d}' for i in range(1,7)];assert all(pid in by for pid in ids)
before_targets={pid:[(t['id'],t['form'],t.get('exposures_in_text')) for t in by[pid].get('new_lexical_targets',[])] for pid in ids};before_occ={pid:{t['id']:by[pid]['text'].count(t['form']) for t in by[pid].get('new_lexical_targets',[])} for pid in ids};before_review={pid:[(t['id'],t['form'],t.get('review_stage')) for t in by[pid].get('review_lexical_targets',[])] for pid in ids};changes=[]
